FORMATS['explorer-island']={name:'Explorer Island',icon:'🧭',emoji:'🧭',color:'#265c49',mode:'SOLO',standalone:'./explorer-island/index.html',description:'Decode map keys, compare landmarks, follow connected routes, and restore the lost treasure map.'};
GAMES.push({id:'geography-7-explorer-island',format:'explorer-island',grade:7,subject:'geography',title:'Explorer Island: The Lost Map',topic:'Map keys · landmark clues · compass directions · treasure routes',minutes:'10–15',items:[]});
document.addEventListener('DOMContentLoaded',()=>{
  const style=document.createElement('style');style.textContent='.art-explorer-island{background:#b6dcdf url("./explorer-island/assets/island.png") center 42%/cover!important;isolation:isolate}.art-explorer-island:before{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#163d3a9c,transparent 60%);z-index:0}.art-explorer-island .island-card-title{position:absolute;left:18px;bottom:15px;color:#fff7df;font-size:19px;font-weight:800;text-shadow:0 2px 8px #163d3a;z-index:1}.art-explorer-island .format-tag{z-index:2}';document.head.append(style);
  const paint=()=>{const card=document.querySelector('[data-edit="geography-7-explorer-island"]')?.closest('.game-card');if(!card||card.dataset.islandPainted)return;card.dataset.islandPainted='true';card.querySelector('.card-art').innerHTML='<span class="island-card-title">The lost map awaits.</span><span class="format-tag">Explorer Island</span>';const details=card.querySelector('.card-details span:last-child');if(details)details.textContent='7 expeditions';const label=card.querySelector('.gx-release-label');if(label)label.textContent='NEW · Map keys + treasure routes';};
  paint();const list=document.querySelector('#games');if(list)new MutationObserver(paint).observe(list,{childList:true});
});
